function PlayerControllerQuadruped:Init(character, isIgnoreJumpHint, WhenPlayerMoveStateChangeds_)
    KTool.SetActive(self.controller.gameObject, true)
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
        behaviourAction.FixedUpdateAction = function(behaviourAction)
            self:FixedUpdate()
        end
    end
    -- ================== self ================:

    self.isIgnoreJumpHint = isIgnoreJumpHint==true

    ------ 绑定 animation clip event:
    assert( self.playerVCamAnimationEvent )
    self.OnWhenCallEvent_Effect = function( name )
        self:WhenCallEvent_Effect( name )
    end
    self.playerVCamAnimationEvent:OnEffect( "+", self.OnWhenCallEvent_Effect )


    ------------------------
    assert( self.catCollider )
    assert( self.catHeadTF )
    self.catColliderRadius = self.catCollider.radius

    assert( self.animator )

    ------------------------

    --self._isJumping = false -- todo: 将被取代 
    self.playerState = PlayerState.Idle
    --self.isMoveLedge = false 
    self.isHitWall = false

    local params = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( params )

    -- 小动作
    self.playIdleMotion = LuaParametersReader.Read( params, "playIdleMotion", LuaParamType.Bool )
    self.idleToSitTime = LuaParametersReader.Read( params, "idleToSitTime", LuaParamType.Float )
    self.sitToLieDownTime = LuaParametersReader.Read( params, "sitToLieDownTime", LuaParamType.Float )

    -- 加速和转向灵敏度
    self.forwardAxisSharpness = LuaParametersReader.Read( params, "forwardAxisSharpness", LuaParamType.Float )     -- 加速到最大速度的灵敏度
    self.turnAxisSharpness = LuaParametersReader.Read( params, "turnAxisSharpness", LuaParamType.Float )        -- 走路时转向的灵敏度
    self.runTurnAxisSharpness = LuaParametersReader.Read( params, "runTurnAxisSharpness", LuaParamType.Float )     -- 跑步时转向的灵敏度

    -- 脊柱弯曲参数
    self.useSpineRigging = LuaParametersReader.Read( params, "useSpineRigging", LuaParamType.Bool )  -- 脊柱弯曲参数
    self.minAngle = LuaParametersReader.Read( params, "minAngle", LuaParamType.Float )            -- 输入方向和移动方向夹角达到这个值的时候开始弯曲
    self.maxAngle = LuaParametersReader.Read( params, "maxAngle", LuaParamType.Float )           -- 输入方向和移动方向夹角达到这个值的时候弯曲到最大

    -- 渐停 
    self.fadeTime = LuaParametersReader.Read( params, "fadeTime", LuaParamType.Float )             -- 花多长时间停下
    self.walkStopRotateTime = LuaParametersReader.Read( params, "walkStopRotateTime", LuaParamType.Float )   -- walk 多长时间以后停止旋转，不要超过fadeTime
    self.runStopRotateTime = LuaParametersReader.Read( params, "runStopRotateTime", LuaParamType.Float )    -- run 多长时间以后停止旋转，不要超过fadeTime

    -- 使用自动跳跃检测
    self.useAutoJumpDetect = LuaParametersReader.Read( params, "useAutoJumpDetect", LuaParamType.Bool )
    self.alwaysJumpDetect = LuaParametersReader.Read( params, "alwaysJumpDetect", LuaParamType.Bool )
    self.jumpDetectInterval = LuaParametersReader.Read( params, "jumpDetectInterval", LuaParamType.Float )
    self.jumpDetectIntervalInIdle = LuaParametersReader.Read( params, "jumpDetectIntervalInIdle", LuaParamType.Float ) -- idle 状态时的 跳跃检测时间间隔

    -- 上跳落点检测
    self.detectDistance = LuaParametersReader.Read( params, "detectDistance", LuaParamType.Float )
    self.detectDistanceNear = LuaParametersReader.Read( params, "detectDistanceNear", LuaParamType.Float ) -- 近处二号线

    self.detectHeightMin = LuaParametersReader.Read( params, "detectHeightMin", LuaParamType.Float ) -- 向下打射线, 终点的高度 (相对于猫的高度)
    self.detectHeightMin = Mathf.Max( self.detectHeightMin, 0.1 )

    self.detectHeightMax = LuaParametersReader.Read( params, "detectHeightMax", LuaParamType.Float ) -- 向下打射线, 起点的高度 (相对于猫的高度)
    self.detectHeightMax = Mathf.Max( self.detectHeightMax, self.detectHeightMin )

    self.jumpUpAngle1 = LuaParametersReader.Read( params, "jumpUpAngle1", LuaParamType.Float )

    self.jumpUpDownLineNums = LuaParametersReader.Read( params, "jumpUpDownLineNums", LuaParamType.Int ) -- 下射射线数量
    self.jumpUpDownLineNums = Mathf.Max( self.jumpUpDownLineNums, 1 ) -- 不能小于 1 

    --self.jumpUpAngle2 = LuaParametersReader.Read( params, "jumpUpAngle2", LuaParamType.Float )


    -- 下跳落点检测
    self.descendDetect = {}

    self.descendDetect.distance = LuaParametersReader.Read( params, "descendDetectDistance", LuaParamType.Float )
    self.descendDetect.heightMin = LuaParametersReader.Read( params, "descendDetectHeightMin", LuaParamType.Float )
    self.descendDetect.heightMax = LuaParametersReader.Read( params, "descendDetectHeightMax", LuaParamType.Float )

    self.descendDetect.jumpDegree1 = LuaParametersReader.Read( params, "descendDetectJumpDegree", LuaParamType.Float ) -- 斜着向下跳 角度-1-, down -> forward 夹角
    self.descendDetect.cosVal1 = Mathf.Cos( Mathf.Deg2Rad * self.descendDetect.jumpDegree1 )
    self.descendDetect.tanVal1 = Mathf.Tan( Mathf.Deg2Rad * self.descendDetect.jumpDegree1 )

    -- self.descendDetectJumpDegree2 = LuaParametersReader.Read( params, "descendDetectJumpDegree2", LuaParamType.Float ) -- 斜着向下跳 角度-2-, down -> forward 夹角
    -- self.descendDetectCosVal2 = Mathf.Cos( Mathf.Deg2Rad * self.descendDetectJumpDegree2 )
    -- self.descendDetectTanVal2 = Mathf.Tan( Mathf.Deg2Rad * self.descendDetectJumpDegree2 )

    self.descendDetect.diagonalLen = (self.descendDetect.heightMax + 0.015 ) / self.descendDetect.cosVal1 -- 第二根射线的长度 (斜向下打的射线)

    -- "下跳落点 到 猫根: 的水平距离, 在下面这对区间内, 是有效的
    self.descendDetect.horizontalDistanceMin = self.descendDetect.distance + self.descendDetect.tanVal1 * self.descendDetect.heightMin 
    self.descendDetect.horizontalDistanceMax = self.descendDetect.distance + self.descendDetect.tanVal1 * self.descendDetect.heightMax



    -- 前跳落点检测
    self.jumpForwardDetectDistance = LuaParametersReader.Read( params, "jumpForwardDetectDistance", LuaParamType.Float )
    self.jumpForwardDetectStartHeight = LuaParametersReader.Read( params, "jumpForwardDetectStartHeight", LuaParamType.Float )
    self.jumpForwardDetectEndHeight = LuaParametersReader.Read( params, "jumpForwardDetectEndHeight", LuaParamType.Float )
    self.jumpForwardAngle1 = LuaParametersReader.Read( params, "jumpForwardAngle1", LuaParamType.Float )
    --self.jumpForwardAngle2 = LuaParametersReader.Read( params, "jumpForwardAngle2", LuaParamType.Float )

    self.jumpForwardDownLineNums = LuaParametersReader.Read( params, "jumpForwardDownLineNums", LuaParamType.Int ) -- 下射射线数量
    self.jumpForwardDownLineNums = Mathf.Max( self.jumpForwardDownLineNums, 1 ) -- 不能小于 1 


    -- 边缘检测 - 移动
    self.moveLedgeDetectStartHeight = LuaParametersReader.Read( params, "moveLedgeDetectStartHeight", LuaParamType.Float )
    self.moveLedgeDetectDistanceH = LuaParametersReader.Read( params, "moveLedgeDetectDistanceH", LuaParamType.Float )
    self.moveLedgeDetectDistanceV = LuaParametersReader.Read( params, "moveLedgeDetectDistanceV", LuaParamType.Float ) -- maxDistance


    -- 边缘检测 - 前跳
    self.jumpLedgeDetectStartHeight = LuaParametersReader.Read( params, "jumpLedgeDetectStartHeight", LuaParamType.Float )
    self.jumpLedgeDetectFrontDistance = LuaParametersReader.Read( params, "jumpLedgeDetectFrontDistance", LuaParamType.Float ) -- 从猫root 向前偏移一段距离, (然后再由此向下打射线)
    self.jumpLedgeDetectDistanceV = LuaParametersReader.Read( params, "jumpLedgeDetectDistanceV", LuaParamType.Float ) -- maxDistance

    -- 检测跳跃路径是否被遮挡 
    self.jumpOcclusionDetectOffset = LuaParametersReader.Read( params, "jumpOcclusionDetectOffset", LuaParamType.Float ) -- 推荐: 0.2


    -- 从猫根节点 到 猫鼻子的距离
    self.headFrontDistance = LuaParametersReader.Read( params, "headFrontDistance", LuaParamType.Float ) -- 推荐: 0.3

    -- 从猫的头部骨骼: Head_M 向前打一根射线, 检测撞墙停步; 这根射线的前出长度 
    self.hitWallDistance = LuaParametersReader.Read( params, "hitWallDistance", LuaParamType.Float ) -- 推荐: 0.3

    -- 检测撞墙停步, 有效夹角 (半角)
    self.hitWallAngle = LuaParametersReader.Read( params, "hitWallAngle", LuaParamType.Float ) -- 推荐: 10 
    self.hitWallAngle = Mathf.Clamp( self.hitWallAngle, 0.1, 90 )
    self.hitWallCosVal = Mathf.Cos( Mathf.Deg2Rad * self.hitWallAngle )

    
    -- 将猫的跳跃 分成 "前摇", "正在跳", "落地" 三个阶段, 使用以下参数来加减它们的 动画速度;
    local idleSpeedParams = LuaParametersReader.Read( params, "idleSpeed", LuaParamType.Vector2 ) -- 推荐: (1.0, 0.5)
    local runSpeedParames = LuaParametersReader.Read( params, "runSpeed", LuaParamType.Vector2 ) -- 推荐: (1.3, 0.5)
    self.idleSpeed      = idleSpeedParams.x 
    self.idleLerpWeight = idleSpeedParams.y
    self.runSpeed       = runSpeedParames.x 
    self.runLerpWeight  = runSpeedParames.y

    local jumpStageSpeed_up      = LuaParametersReader.Read( params, "jumpStageSpeed_up",      LuaParamType.Vector4 ) -- 推荐: ( 2.3, 1.3, 1.0, 0.6 )
    local jumpStageSpeed_down    = LuaParametersReader.Read( params, "jumpStageSpeed_down",    LuaParamType.Vector4 ) -- 推荐: ( 1.5, 0.9, 1.0, 0.7 )
    local jumpStageSpeed_forward = LuaParametersReader.Read( params, "jumpStageSpeed_forward", LuaParamType.Vector4 ) -- 推荐: ( 1.0, 1.0, 1.0, 1.0 )

    self.jumpStageSpeeds = {}
    self.jumpStageSpeeds[JumpType.Up] = {}
    self.jumpStageSpeeds[JumpType.Up][JumpAnimationStage.Prepare] = jumpStageSpeed_up.x
    self.jumpStageSpeeds[JumpType.Up][JumpAnimationStage.Jumping] = jumpStageSpeed_up.y
    self.jumpStageSpeeds[JumpType.Up][JumpAnimationStage.Landing] = jumpStageSpeed_up.z
    self.jumpStageSpeeds[JumpType.Up]["lerpWeight"]               =  jumpStageSpeed_up.w 

    self.jumpStageSpeeds[JumpType.Down] = {}
    self.jumpStageSpeeds[JumpType.Down][JumpAnimationStage.Prepare] = jumpStageSpeed_down.x
    self.jumpStageSpeeds[JumpType.Down][JumpAnimationStage.Jumping] = jumpStageSpeed_down.y
    self.jumpStageSpeeds[JumpType.Down][JumpAnimationStage.Landing] = jumpStageSpeed_down.z
    self.jumpStageSpeeds[JumpType.Down]["lerpWeight"]               =  jumpStageSpeed_down.w 

    self.jumpStageSpeeds[JumpType.Forward] = {}
    self.jumpStageSpeeds[JumpType.Forward][JumpAnimationStage.Prepare] = jumpStageSpeed_forward.x
    self.jumpStageSpeeds[JumpType.Forward][JumpAnimationStage.Jumping] = jumpStageSpeed_forward.y
    self.jumpStageSpeeds[JumpType.Forward][JumpAnimationStage.Landing] = jumpStageSpeed_forward.z
    self.jumpStageSpeeds[JumpType.Forward]["lerpWeight"]               =  jumpStageSpeed_forward.w 


    --------
    assert( self.rootMotion )
    local moveScales_walk    = LuaParametersReader.Read( params, "moveScales_walk",   LuaParamType.Float ) -- rootMotion xz平面位移倍率; (walk) 推荐: 0.8
    local moveScales_run     = LuaParametersReader.Read( params, "moveScales_run",    LuaParamType.Float ) -- rootMotion xz平面位移倍率; (run) 推荐: 1.2
    self.rootMotionCustoms = RootMotionCustoms.New( self.rootMotion, moveScales_walk, moveScales_run, function()
        return (self.playerState == PlayerState.Move)
    end )


    -- =======================================================
    self._character = character

    if isNotNull(self._character.useUpdate) then 
        self._character.useUpdate = true
    end


    self._character.useRootMotionMove = true
    self._riggingSpine = self._character:GetComponentInChildren( typeof(RiggingSpine) )
    assert( self._riggingSpine )

    self._characterMotor = self._character.Motor -- 缓存引用

    -- 跳跃落点 平滑设置:
    self._jumpUpSmooth = JumpPositionSmooth.New() 
    self._jumpDownSmooth = JumpPositionSmooth.New() 
    self._jumpForwardSmooth = JumpPositionSmooth.New() 
    self._jumpUpSmooth:Init(        JumpHintType.Up,        self._characterMotor, self.jumpDetectInterval)
    self._jumpDownSmooth:Init(      JumpHintType.Down,      self._characterMotor, self.jumpDetectInterval)
    self._jumpForwardSmooth:Init(   JumpHintType.Forward,   self._characterMotor, self.jumpDetectInterval)


    assert( type(WhenPlayerMoveStateChangeds_) == "table" )
    for _,func in pairs(WhenPlayerMoveStateChangeds_) do 
        assert( type(func) == "function" )
        table.insert( self.WhenPlayerMoveStateChangeds, func )
    end

    -- 主动触发一次 callback
    self:UpdateFootStepState( 0 )



    ----- 可视化 debug: ----- 
    assert( self.catControllerDebugBH )
    self.catControllerDebug = DreamSpaceLuaUtils.GetLuaScr(self.catControllerDebugBH.gameObject, "Game.DreamSpace.DebugTools.CatControllerDebug" )
    assert( self.catControllerDebug )
 

end


