    self.playerVCamAnimationEvent:OnEffect( "-", self.OnWhenCallEvent_Effect )
    self.OnWhenCallEvent_Effect = nil

    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
