-- =========================================== Self ================================================ --



function PlayerControllerQuadruped:Update()

    if self.playerState == PlayerState.Jump then 

        if DreamSpaceStates.subPanelFreesInPC.jump ~= false then 
            DreamSpaceStates.subPanelFreesInPC.jump = false -- PC 版 禁止打开 ui 子界面 
        end
        
        local animatorStateInfo = self.animator:GetCurrentAnimatorStateInfo(0) -- AnimatorStateInfo
        if animatorStateInfo:IsName("JumpUp") then 
            self.animator:MatchTarget(
                self._climbPoint.pos - self._characterMotor.CharacterForward * 0.2, -- !!! 目标上跳点, 后撤一段以规避 猫上跳时穿模
                self._characterMotor.TransientRotation,
                AvatarTarget.Root, 
                matchTargetWeightMask_Up,
                0.25,  -- [0.18, 0.385]
                0.65   -- 0.65
            )
        elseif animatorStateInfo:IsName("JumpDown") then 
            self.animator:MatchTarget(
                self._landPoint.pos,
                self._characterMotor.TransientRotation,
                AvatarTarget.Root, 
                matchTargetWeightMask_Down,
                0.35,  -- [0.334, 0.476]
                0.60   -- [0.576]
            )
        elseif animatorStateInfo:IsName("JumpForward") then 
            self.animator:MatchTarget(
                self._jumpForwardLandPos,
                self._characterMotor.TransientRotation,
                AvatarTarget.Root, 
                matchTargetWeightMask_Forward,
                0.25,  -- [0.18, ]
                0.85    -- [ , 0.78]
            )
        end 

    else 
        if DreamSpaceStates.subPanelFreesInPC.jump ~= true then 
            DreamSpaceStates.subPanelFreesInPC.jump = true  -- PC 版 允许打开 ui 子界面 
        end
    end

end



function PlayerControllerQuadruped:FixedUpdate()

    -- 其实目前放此处意义不大...
    if self.playerState == PlayerState.Move then 
        self.isHitWall = self:HeadFrontDetect()
    end
end




function PlayerControllerQuadruped:DetachCharacter()
    self._character = nil
    self._riggingSpine = nil
end


function PlayerControllerQuadruped:SetCharacterFSM()
    if isNull( self._fsm ) then
        local fsm = FSM()
        local idleState = fsm:AddState(PlayerState.Idle)
        local moveState = fsm:AddState(PlayerState.Move)
        local jumpState = fsm:AddState(PlayerState.Jump)
        fsm.currentState = idleState

        idleState.onEnterState = function( fsm_, selfState_, fromState_, param_ )
            self:IdleEnterState(fsm_, selfState_, fromState_, param_)
        end

        idleState.onUpdate = function(fsm_, selfState_, deltaTime_)
            self:IdleUpdate(fsm_, selfState_, deltaTime_)
        end

        idleState.onExitState = function(fsm, selfState, toState, param)
            self:IdleExitState(fsm, selfState, toState, param)
        end

        idleState.onCanTransitionTo = function(fsm, selfState, toState, param)
            return self:IdleCanTransitionTo(fsm, selfState, toState, param)
        end
        
        moveState.onEnterState = function(fsm, selfState, fromState, param)
            self:MoveEnterState(fsm, selfState, fromState, param)
        end
        
        moveState.onUpdate = function(fsm, selfState, deltaTime)
            self:MoveUpdate(fsm, selfState, deltaTime)
        end

        moveState.onExitState = function(fsm, selfState, toState, param)
            self:MoveExitState(fsm, selfState, toState, param)
        end

        moveState.onCanTransitionTo = function(fsm, selfState, toState, param)
            return self:MoveCanTransitionTo(fsm, selfState, toState, param)
        end

        jumpState.onEnterState = function(fsm, selfState, fromState, param)
            self:JumpEnterState(fsm, selfState, fromState, param)
        end

        jumpState.onUpdate = function(fsm, selfState, deltaTime)
            self:JumpUpdate(fsm, selfState, deltaTime)
        end

        jumpState.onExitState = function(fsm, selfState, toState, param)
            self:JumpExitState(fsm, selfState, toState, param)
        end

        jumpState.onCanTransitionTo = function(fsm, selfState, toState, param)
            return self:JumpCanTransitionTo(fsm, selfState, toState, param)
        end

        jumpState.onCanTransitionFrom = function(fsm, selfState, fromState, param)
            return self:JumpCanTransitionFrom(fsm, selfState, fromState, param)
        end
        self._fsm = fsm
        assert( not isNull(self._fsm) )
    end
    assert( not isNull(self._fsm) )
    self._character:SetFSM(self._fsm)
end



function PlayerControllerQuadruped:ResetCharacterFSM()
    self._character:SetFSM(nil)
end

function PlayerControllerQuadruped:MoveStart()

    local flag = self._character.FSM:TryTransitionTo(PlayerState.Move)

    self._hasMoveInput = true
    self._exitIdleMotionSignal = true
end

function PlayerControllerQuadruped:Meow()
    Events.Broadcast(DreamSpaceStates.EventNames.OnMeow)
end


function PlayerControllerQuadruped:Move(moveInput)

    if self._character.FSM:IsInState(PlayerState.Move) then
        self._lastMoveInput = self._moveInput
        self._moveInput = moveInput
        self._moveDir = self._moveInput.normalized
        if moveInput.sqrMagnitude > 0.00001 then 
            self._moveDir = self._moveInput.normalized
        end 
    else
        self:MoveStart()
    end
end


function PlayerControllerQuadruped:MoveEnd()
    self._character.FSM:TryTransitionTo(PlayerState.Idle)
    self._hasMoveInput = false
end


-- 猫跳跃后, 所有 hint ui 都要消失
function PlayerControllerQuadruped:HideAllHints()
    if JumpPositionSmooth.GetActive() then
        self._jumpUpSmooth:SetShow(false)
        self._jumpDownSmooth:SetShow(false)
        self._jumpForwardSmooth:SetShow(false)
    else 
        JumpHint.HideJumpHint(JumpHintType.Up)
        JumpHint.HideJumpHint(JumpHintType.Down)
        JumpHint.HideJumpHint(JumpHintType.Forward)
    end
end



function PlayerControllerQuadruped:JumpUp()
    self._exitIdleMotionSignal = true
    self._jumpType = JumpType.Up
    self._character.FSM:TryTransitionTo(PlayerState.Jump)
    self:HideAllHints()
end



function PlayerControllerQuadruped:JumpDown()
    self._exitIdleMotionSignal = true
    self._jumpType = JumpType.Down
    self._character.FSM:TryTransitionTo(PlayerState.Jump)
    self:HideAllHints()
end

function PlayerControllerQuadruped:JumpForward()
    self._exitIdleMotionSignal = true
    self._jumpType = JumpType.Forward
    self._character.FSM:TryTransitionTo(PlayerState.Jump)
    self:HideAllHints()
end


function PlayerControllerQuadruped:SwitchIn(roleMoveState_, rotate_)
    self._moveDir = rotate_ * Vector3.forward
    self._moveInput = Vector3.zero
    self._lastMoveInput = Vector3.zero
    if roleMoveState_ == RoleMoveState.MoveEnd then
        self:MoveEnd()
    else
        self:MoveStart()
    end
    self._character.useGravity = true
    self.playIdleMotion = true
end


function PlayerControllerQuadruped:SwitchOut()
    self:MoveEnd()
    self._exitIdleMotionSignal = true
    self._character.useGravity = false
    self.playIdleMotion = false
end


function PlayerControllerQuadruped:SlowDownMoveInput(val_)
    return val_.normalized / 1000.0
end


-- =========================================== Idle状态 ================================================ --

function PlayerControllerQuadruped:IdleEnterState(fsm, selfState, fromState, param)
    self.playerState = PlayerState.Idle
    self._idleTimer = 0
    self._idleMotioning = false
    self._idleMotionExitting = false
    if self.useAutoJumpDetect then
        self:JumpDetect()
    end

    self:CalculateIdleAnimatiorSpeed()

    self._idleMotionTimer = 0 -- 每次进入 idle 都要重置为 0
end


function PlayerControllerQuadruped:IdleUpdate(fsm, selfState, deltaTime)

    self:CalculateIdleAnimatiorSpeed(deltaTime)

    -- 跳跃检测:
    -- 为确保一定能生成跳跃点, 现在在 idle 阶段也要定期检测
    if (self.useAutoJumpDetect and self.alwaysJumpDetect) then
        self._jumpDetectTimer = self._jumpDetectTimer + deltaTime
        if (self._jumpDetectTimer >= self.jumpDetectIntervalInIdle) then
            self._jumpDetectTimer = 0
            --print( "idle JumpDetect" )
            self:JumpDetect()
        end
    end


    if self.playIdleMotion then
        -- 播小动作
        if self._character.AnimationAdapter:GetCurrentAnimatorStateInfo(0):IsName("Idle") then
            self._idleTimer = self._idleTimer + Time.deltaTime
            if self._idleTimer > 0.5 then
                -- 处于idle状态了
                self._idleMotionTimer = self._idleMotionTimer + Time.deltaTime
                if self._idleMotionTimer > self.idleToSitTime then
                    --print( "开始坐下" )
                    self._idleMotionTimer = 0
                    self._idleMotioning = true
                    self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.IdleToSit, 0)
                end
            end
        elseif self._character.AnimationAdapter:GetCurrentAnimatorStateInfo(0):IsName("Sitting") then
            self._idleMotionTimer = self._idleMotionTimer + Time.deltaTime
            if self._idleMotionTimer > self.sitToLieDownTime then
                --print( "开始躺下" )
                self._idleMotionTimer = 0
                self._idleMotioning = true
                self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.SitToLying, 0)
            end
        else
            self._idleTimer = 0
        end
    end
    -- 退出小动作
    if self._exitIdleMotionSignal then
        self:TryExitIdleModtion()
    end
    self._exitIdleMotionSignal = false
    -- 小动作退出完成
    if self._character.AnimationAdapter:GetFloat(AnimatorHash.IdleMotionCanInterrupted) > 0 then
        self._idleMotionExitting = false
    end
    -- 移动渐停
    if self._fading then
        self:UpdateFadeIdle(Time.deltaTime)
    end

    --print( "IdleUpdate" )
    self._jumpUpSmooth:Update()
    self._jumpDownSmooth:Update()
    self._jumpForwardSmooth:Update()
end


function PlayerControllerQuadruped:IdleExitState(fsm, selfState, toState, param)

    self:CalculateIdleAnimatiorSpeed()

    if (self._fading) then
        self._fading = false
        if (self._fadeCallback ~= nil) then
            self._fadeCallback()
            self._fadeCallback = nil
        end
        if (self._stopRotateCallback ~= nil) then
            self._stopRotateCallback()
            self._stopRotateCallback = nil
        end
    end

    if (toState.stateId ~= PlayerState.Jump) then
        -- 清除计算结果，防止误跳
        self._canJumpUp = false
        self._canJumpDown = false
        self._canJumpForward = false
    end
    
    -- 清除跳跃的UI提示
    if (self.useAutoJumpDetect and self.HideJumpHint ~= nil) then
        self.HideJumpHint(JumpHintType.Up)
        self.HideJumpHint(JumpHintType.Forward)
        self.HideJumpHint(JumpHintType.Down)
    end
end


function PlayerControllerQuadruped:IdleCanTransitionTo(fsm, selfState, toState, param)
    if (self._idleMotioning or self._idleMotionExitting) then
        return false
    end
    return true
end



-- =========================================== Move状态 ================================================ --


function PlayerControllerQuadruped:MoveEnterState(fsm, selfState, fromState, param)
    self.playerState = PlayerState.Move
    --print( "-- move enter --" )
    self._character.useRootMotionMove = true
    self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.Locomotion, 0.3)
    self._jumpDetectTimer = 0
    self:CalculateRunAnimatiorSpeed()
end


function PlayerControllerQuadruped:MoveUpdate(fsm, selfState, deltaTime)
    -- 边缘检测
    local isLedge = self:DetectMoveLedge()
    --local isLedge = self.isMoveLedge

    --local isLedge = false
    self._character.useRootMotionMove = not isLedge    -- 在边缘的时候取消位移
    if (isLedge) then
        -- 在边缘的时候就停下移动的动画
        self._forwardValue = Mathf.Lerp(self._forwardValue, 0, 0.2)
    else

        -- [-- 撞墙停步 检测 --]
        --local isFightWall = self._character:DetectFightWall() -- 弃用旧的
        --local isFightWall = self:HeadFrontDetect()
        local isFightWall = self.isHitWall
        if (isFightWall) then
            -- 撞墙的时候就停下移动的动画
            --self._forwardValue = Mathf.Lerp(self._forwardValue, 0, 0.2)
            self._forwardValue = Mathf.Lerp(self._forwardValue, 0, 0.5)
        else
            self._forwardValue = Mathf.Lerp(self._forwardValue, self._moveInput.magnitude, 
                1.0 - math.exp(-self.forwardAxisSharpness * deltaTime))
        end
    end


    self:UpdateFootStepState( self._forwardValue ) -- 在 animator set 前调用
    
    self._character.AnimationAdapter:SetFloat(AnimatorHash.Forward, self._forwardValue)
    self._character:LerpRotate(self._moveDir, self._forwardValue < 0.9 and self.turnAxisSharpness or self.runTurnAxisSharpness)
    if (self.useSpineRigging and self._riggingSpine) then
        self:CurveSpine(self._moveDir)
    end 

    if (self.useAutoJumpDetect and self.alwaysJumpDetect) then
        self._jumpDetectTimer = self._jumpDetectTimer + deltaTime
        if (self._jumpDetectTimer >= self.jumpDetectInterval) then
            self._jumpDetectTimer = 0
            self:JumpDetect()
        end
    end

    self:CalculateRunAnimatiorSpeed(deltaTime)

    self._jumpUpSmooth:Update()
    self._jumpDownSmooth:Update()
    self._jumpForwardSmooth:Update()
end



function PlayerControllerQuadruped:MoveExitState(fsm, selfState, toState, param)
    --print( "-- move exit --" )
    if (self._riggingSpine) then
        self._riggingSpine.targetWeight = 0
    end
    
    self:FadeIdle(self.fadeTime, self._forwardValue < 0.9 and self.walkStopRotateTime or self.runStopRotateTime
        , self._forwardValue, 0, AnimationCurve.EaseInOut(0,0,1,1), function()
        self._forwardValue = 0
        self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.Idle, 0.1)
    end)

    self:UpdateFootStepState( 0 ) -- to Idle

    self:CalculateRunAnimatiorSpeed()
    
    -- 边缘检测
    self._character.useRootMotionMove = not self:DetectMoveLedge()
    --self._character.useRootMotionMove = not self.isMoveLedge
end



function PlayerControllerQuadruped:MoveCanTransitionTo(fsm, selfState, toState, param)
    local toMove = toState.stateId == PlayerState.Move
    if (toMove) then
        return false
    end
    return true
end



-- =========================================== Jump状态 ================================================ --


function PlayerControllerQuadruped:GetDeltaTime()
    -- Character.cs 存在一个更新, 在更新进包之前, .useUpdate 是不存在的
    if isNotNull(self._character.useUpdate) then 
        return ( self._character.useUpdate==true and Time.deltaTime or Time.fixedDeltaTime )
    else 
        return Time.deltaTime
    end 
end


function PlayerControllerQuadruped:CalculateIdleAnimatiorSpeed(deltaTime_)
    local deltaTime = isNotNull(deltaTime_) and deltaTime_ or self:GetDeltaTime()
    self.animator.speed = Mathf.MoveTowards( self.animator.speed, self.idleSpeed, deltaTime * self.idleLerpWeight )
end


function PlayerControllerQuadruped:CalculateRunAnimatiorSpeed(deltaTime_)
    local deltaTime = isNotNull(deltaTime_) and deltaTime_ or self:GetDeltaTime()
    self.animator.speed = Mathf.MoveTowards( self.animator.speed, self.runSpeed, deltaTime * self.runLerpWeight )
end


function PlayerControllerQuadruped:CalculateJumpAnimatorSpeed(deltaTime_)
    local deltaTime = isNotNull(deltaTime_) and deltaTime_ or self:GetDeltaTime()
    self.animator.speed = Mathf.MoveTowards(  
        self.animator.speed, 
        self.jumpStageSpeeds[self._jumpType][self.jumpAnimationStage],
        self.jumpStageSpeeds[self._jumpType]["lerpWeight"] * deltaTime
    ) 
end




function PlayerControllerQuadruped:JumpEnterState(fsm, selfState, fromState, param)
    self.playerState = PlayerState.Jump
    self._character.useRootMotionMove = true
    self._character.useGravity = false
    self._characterMotor:SetGroundSolvingActivation(false)
    self._characterMotor:SetCapsuleCollisionsActivation(false)
    self._characterMotor:SetMovementCollisionsSolvingActivation(false)

    --Application.targetFrameRate = 60

    self.jumpAnimationStage = JumpAnimationStage.Prepare
    self:CalculateJumpAnimatorSpeed()

    self._jumpCanInterrupted = false
    -- 清除计算结果，防止连跳
    self._canJumpUp = false
    self._canJumpDown = false
    self._canJumpForward = false

    if (self._jumpType == JumpType.Up) then
        --self:CalculateRiseScale()
        self._character:ForceUnground(1)
        self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.JumpUp, 0.1)
        self._character.AnimationAdapter:Refresh()
        
        -- 转向
        local dir = Vector3.ProjectOnPlane(self._upDetectPos - self._characterMotor.TransientPosition, Vector3.up)
        self._character:FixedDurationRotate(dir, 0.2, AnimationCurve.Linear(0,0,1,1))

    elseif (self._jumpType == JumpType.Down) then
        --self:CalculateDescentScale()
        self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.JumpDown, 0.1)
        self._character.AnimationAdapter:Refresh()

        -- 转向
        local dir = Vector3.ProjectOnPlane(self._landDetectPos - self._characterMotor.TransientPosition, Vector3.up)
        self._character:FixedDurationRotate(dir, 0.2, AnimationCurve.Linear(0,0,1,1))

    elseif (self._jumpType == JumpType.Forward) then
        --self:CalculateJumpForwardScaleH()
        self:JumpForwardVerticalModify()
        self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.JumpForward, 0.1)
        self._character.AnimationAdapter:Refresh()
        
        -- 转向
        local dir = Vector3.ProjectOnPlane(self._jumpForwardDownDetectPos - self._characterMotor.TransientPosition, Vector3.up)
        self._character:FixedDurationRotate(dir, 0.2, AnimationCurve.Linear(0,0,1,1))
    end

    --self:UpdateFootStepState( 0, FootStepState.JumpStart ) -- to  JumpStart
end




function PlayerControllerQuadruped:JumpUpdate(fsm, selfState, deltaTime)
    if (not self._character.AnimationAdapter:IsInTransition(0)
        and self._character.AnimationAdapter:GetCurrentAnimatorStateInfo(0):IsName("Idle")) 
    then
        self._jumpCanInterrupted = true
        fsm:TryTransitionTo(PlayerState.Idle)
    end

    -- 下面的 Multiply 每帧都会调用, 将动画片段中一部分帧 做拉伸, (还有一部分则不拉伸)
    -- 从而让 动画自己的 rootmotion 控制猫完成整个跳跃运动
    -- 如果全程都写入 RootMotionMoveMultiply(1,1), 则能发现猫完成了 原始跳跃动画所提供的一段位移...

    if (self._jumpType == JumpType.Up) then
        if (self._character.AnimationAdapter:GetFloat(AnimatorHash.RiseScale) > 0.5) then
            --self._character:RootMotionMoveMultiply(self._riseScaleH, self._riseScaleV)
            self._character:RootMotionMoveMultiply(1, 1)
        else
            self._character:RootMotionMoveMultiply(1, 1)
        end

        if (self._character.AnimationAdapter:GetFloat(_JumpStageSpeedId) > 0.5) then
            if self.jumpAnimationStage ~= JumpAnimationStage.Jumping then 
                self.jumpAnimationStage = JumpAnimationStage.Jumping
            end 
        else
            if self.jumpAnimationStage == JumpAnimationStage.Jumping then 
                self.jumpAnimationStage = JumpAnimationStage.Landing
            end 
        end

    elseif (self._jumpType == JumpType.Down) then
        if (self._character.AnimationAdapter:GetFloat(AnimatorHash.DescendScale) > 0.5) then
            --self._character:RootMotionMoveMultiply(self._descendScaleH, self._descendScaleV)
            self._character:RootMotionMoveMultiply(1, 1)
        else
            self._character:RootMotionMoveMultiply(1, 1)
        end

        if (self._character.AnimationAdapter:GetFloat(_JumpStageSpeedId) > 0.5) then
            if self.jumpAnimationStage ~= JumpAnimationStage.Jumping then 
                self.jumpAnimationStage = JumpAnimationStage.Jumping
            end 
        else
            if self.jumpAnimationStage == JumpAnimationStage.Jumping then 
                self.jumpAnimationStage = JumpAnimationStage.Landing
            end 
        end

    elseif (self._jumpType == JumpType.Forward) then
        if (self._character.AnimationAdapter:GetFloat(AnimatorHash.ForwardScale) > 0.5) then
            if self.jumpAnimationStage ~= JumpAnimationStage.Jumping then 
                self.jumpAnimationStage = JumpAnimationStage.Jumping
            end 
            --self._character:RootMotionMoveMultiply(self._jumpForwardScaleH, 1)
            self._character:RootMotionMoveMultiply(1, 1)
        else
            if self.jumpAnimationStage == JumpAnimationStage.Jumping then 
                self.jumpAnimationStage = JumpAnimationStage.Landing
            end 
            self._character:RootMotionMoveMultiply(1, 1)
        end

        self:UpdateJumpForwardVerticalModify(deltaTime)
    end

    self:CalculateJumpAnimatorSpeed(deltaTime) 

    if (not self._character.AnimationAdapter:IsInTransition(0)
        and self._character.AnimationAdapter:GetFloat(AnimatorHash.JumpCanInterrupted) > 0.5) then
        self._jumpCanInterrupted = true
    end

    self._jumpUpSmooth:Update(self._jumpType)
    self._jumpDownSmooth:Update(self._jumpType)
    self._jumpForwardSmooth:Update(self._jumpType)
end



function PlayerControllerQuadruped:JumpExitState(fsm, selfState, toState, param)
    self._character.useGravity = true
    self._characterMotor:SetGroundSolvingActivation(true)
    self._characterMotor:SetCapsuleCollisionsActivation(true)
    self._characterMotor:SetMovementCollisionsSolvingActivation(true)
    self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.Idle, 0.1)

    self:CalculateJumpAnimatorSpeed()
    --Application.targetFrameRate = 30
end



function PlayerControllerQuadruped:JumpCanTransitionTo(fsm, selfState, toState, param)
    -- 增加一个idle的判定，跳跃的时候如果有移动输入，会触发movestart和moveend
    -- moveend会尝试进入idle状态，这里是防止moveend进入idle状态
    local toIdle = toState.stateId == PlayerState.Idle
    if toIdle then
        return self._jumpCanInterrupted
    end

    local toMove = toState.stateId == PlayerState.Move
    if toMove then
        return self._jumpCanInterrupted
    end

    local toJump = toState.stateId == PlayerState.Jump
    if toJump then
        return self._jumpCanInterrupted
    end

    return true
end



function PlayerControllerQuadruped:JumpCanTransitionFrom(fsm, selfState, fromState, param)
    return (self._jumpType == JumpType.Up and self._canJumpUp)
        or (self._jumpType == JumpType.Down and self._canJumpDown)
        or (self._jumpType == JumpType.Forward and self._canJumpForward)
end



-- 脊柱弯曲
function PlayerControllerQuadruped:CurveSpine(moveDir)
    -- 计算弯曲方向
    local targetForward = moveDir.normalized

    local selfForward = self._characterMotor.CharacterForward
    local sign = Mathf.Sign(Vector3.Cross(selfForward, targetForward).y)
    -- 计算转向角度
    local cosValue = Vector3.Dot(selfForward, targetForward)
    local angle1 = Mathf.Acos(cosValue) * Mathf.Rad2Deg

    -- 当转向角度满足条件，设置弯曲权重
    if self.minAngle <= angle1 then
        local weight = sign * (angle1 - self.minAngle) / (self.maxAngle - self.minAngle)
        self._riggingSpine.targetWeight = Mathf.Clamp(weight, -1, 1)
    else
        self._riggingSpine.targetWeight = 0
    end
end



-- =========================================== 走路渐停 ================================================ --


function PlayerControllerQuadruped:FadeIdle(fadeTime_, stopRotateTime, fromValue, toValue, fadeCurve, callback)
    self._fading = true
    self._fadeTime = fadeTime_
    self._stopRotateTime = stopRotateTime
    self._fadeTimer = 0
    self._fromValue = fromValue
    self._toValue = toValue
    self._fadeCurve = fadeCurve
    self._fadeCallback = callback
    self._stopRotateCallback = function() 
        self._character:StopTurning() 
    end
end



function PlayerControllerQuadruped:UpdateFadeIdle(deltaTime)
    if self._fadeTimer >= self._stopRotateTime then
    self._stopRotateCallback()
    end
    local progress = self._fadeTimer / self._fadeTime

    if progress >= 1 then
        self._fading = false
        if self._fadeCallback ~= nil then
            self._fadeCallback()
            self._fadeCallback = nil
        end
    else
        self._fadeTimer = self._fadeTimer + deltaTime
        local t = self._fadeCurve:Evaluate(progress)
        local targetValue = Mathf.Lerp(self._fromValue, self._toValue, t)
        self._character.AnimationAdapter:SetFloat(AnimatorHash.Forward, targetValue)
    end
end



function PlayerControllerQuadruped:DelayStop()
    self._character:StopTurning()
end



