-- 上跳检测:
function PlayerControllerQuadruped:DetectClimbable()
    
    local headTopPos = self._characterMotor.TransientPosition + Vector3.up * self.detectHeightMax
    local downDistance = self.detectHeightMax - self.detectHeightMin + 0.01 + self._detectDelta -- 0.01 是角色控制器的碰撞默认会有一点点offfset motor.CollisionOffset
    --local forwardDistance = self.detectDistance 
    local angle1 = self.jumpUpAngle1

    -- 打多条射线检测
    local dirMid = self._characterMotor.CharacterForward
    local dirLeft1 = Quaternion.AngleAxis(-angle1, Vector3.up) * self._characterMotor.CharacterForward
    local dirRight1 = Quaternion.AngleAxis(angle1, Vector3.up) * self._characterMotor.CharacterForward

    if      self:SingleRayUpDetect( "up", "Mid", headTopPos, dirMid, downDistance, true)
        --or  self:SingleRayUpDetect( "up", "Left1", headTopPos, dirLeft1, downDistance, false)
        --or  self:SingleRayUpDetect( "up", "Right1", headTopPos, dirRight1, downDistance, false)
    then 
        return true
    end

    -- 本次射线没能检测到 合格的 上跳点, 但这不意味着不能跳, 有可能是前方的高台 厚度不够, 下射射线打到 高台后方去了
    -- 廉价的补救措施:
    --     如果上一次得到的有效的 _climbPoint.pos 依然在合理区间内, 那就继续沿用它:
    if self:CanUseLastClimbPos() == true then 
        return true
    end     

    -- 实在不行, 才会把点归零
    self._climbPoint.pos = Vector3.zero
    self._climbPoint.hitCollider = nil
    
    return false
end 




-- 上跳用
-- returnL bool
function PlayerControllerQuadruped:SingleRayUpDetect( bigType_, lineType_, originTopPos, dir, downDistance, isMid_)

    -- [-- 1 --]: "向前打射线"
    -- 从猫头顶向前打射线1, 收集这个距离内打中的最近点的 distance;
    local raycastHit1, isHit1 = DreamSpaceLuaUtils.RaycastNearestNonAlloc( originTopPos, dir, self.detectDistance, jumpCollideLayerMask, self._queryTriggerInteraction )

    
    local nearestDistance = isHit1 and raycastHit1.distance or 10000

    -- 最远前射距离, 如果撞墙, 这个距离会被缩短 (离墙大约 0.1 米)
    local forwardDistance = self.detectDistance 
    if isHit1 and (nearestDistance > 0.1)  then 
        forwardDistance = nearestDistance - 0.1 -- 在大斜角时, 其实这个计算不能保证离墙 0.1 米, 但暂掠过
    end

    
    self.catControllerDebug:UpdateForwardOrUpLines( bigType_, lineType_, originTopPos, dir, forwardDistance , downDistance ) -- todo: 画两根射线


    if (isHit1 == false ) or ( nearestDistance > 0.1 ) then

        local hitInfo2 = nil
        local isHit2 = false 
        if isHit1 then
            -- 前射射线命中, 说明撞墙了:
            local downDetectTopPos2 = originTopPos + (dir * forwardDistance)
            -- [-- 2 --]:  "向下打射线"
            -- 从射线1终点, 向下打射线2, 捕获打中的物体 (上跳平台)
            hitInfo2, isHit2 = DreamSpaceLuaUtils.RaycastNearestNonAlloc( downDetectTopPos2, Vector3.down, downDistance, jumpCollideLayerMask, self._queryTriggerInteraction )
            
        else
            -- 前射射线没有命中, 说明需要做多段 下射检测, 来避免 高台太薄的问题
            local stepLen = forwardDistance / (self.jumpUpDownLineNums + 0.0001) 
            stepLen = stepLen * 0.9 -- 适当变小一点

            self.catControllerDebug:UpdateSingleLine( bigType_ .. lineType_ .. "_1", originTopPos, originTopPos + dir * forwardDistance, 0.015 ) -- todo: 画射线
            
            -- 由远及近 向下打射线
            for i=0, self.jumpUpDownLineNums-1 do

                local downDetectTopPos2 = originTopPos + (dir * (forwardDistance - stepLen * i))
                
                -- [-- 2 --]:  "向下打射线"
                -- 向下打射线2, 捕获打中的物体 (上跳平台)
                hitInfo2, isHit2 = DreamSpaceLuaUtils.RaycastNearestNonAlloc( downDetectTopPos2, Vector3.down, downDistance, jumpCollideLayerMask, self._queryTriggerInteraction )

                if isHit2 and self:IsTargetTag(hitInfo2.transform) then 
                    self.catControllerDebug:UpdateSingleLine( bigType_ .. lineType_ .. "_2", downDetectTopPos2, downDetectTopPos2 + Vector3.down * downDistance, 0.015 ) -- todo: 画射线
                    break
                end 
            end 
        end
        

        if isHit2  and self:IsTargetTag(hitInfo2.transform) then

            local hitPos2 = hitInfo2.point
            self._upDetectPos = hitPos2
            --- 

            local point = self._upDetectPos + Vector3.down * self._detectDelta
            local headTopPos = self._characterMotor.TransientPosition
            headTopPos.y = point.y

            local direction = Vector3.ProjectOnPlane(point - headTopPos, Vector3.up).normalized

            -- [--3--]:  "判断"
            -- 从射线1起点, 平行于 xz 平面, 沿着 hitPos2 下面一点的高度, 打向 候选跳跃点
            -- 看看中间是否能命中 射线2 命中的物体
            local hitInfo3, isHit3 = DreamSpaceLuaUtils.RaycastNearestNonAlloc(headTopPos, direction, forwardDistance, jumpCollideLayerMask, self._queryTriggerInteraction)

            self.catControllerDebug:UpdateJumpLedgeLine_2( headTopPos, headTopPos + direction * forwardDistance, isHit3 ) -- todo: 画射线
            
            if isHit3  and self:IsTargetTag(hitInfo3.transform) then

                local climbPos = hitInfo3.point
                climbPos.y = self._upDetectPos.y
                -- 现在, climbPos 就是一个 候选 上跳点;

                if self:IsTargetClimbPosLegal( climbPos ) then 
                    self._climbPoint.pos = climbPos
                    self._climbPoint.hitCollider = hitInfo3.collider
                    return true
                end

            end
            -- todo: 不要在此处主动将 _climbPoint.pos 归零
            --self._climbPoint.pos = Vector3.zero
            --self._climbPoint.hitCollider = = nil
        end 
    end
    
    return false
end



-- 检测 climbPos_ 是否为一个合格的 上跳点
function PlayerControllerQuadruped:IsTargetClimbPosLegal( climbPos_ )

    local horizontalDir = Vector3.ProjectOnPlane(climbPos_ - self._characterMotor.TransientPosition, Vector3.up).normalized
    
    -- [--4--]: "最终跳跃点, 必须在猫的身体前方"
    local catFrontPos = self._characterMotor.TransientPosition + horizontalDir * (self.headFrontDistance * 0.8 )
    local horizontalOffset = climbPos_ - catFrontPos
    horizontalOffset. y = 0.0 

    if Vector3.Dot( horizontalOffset, horizontalDir ) > 0 then 

        -- [--5--]: "检查跳跃路径上是否存在遮挡"
        local pos1 = self._characterMotor.TransientPosition + Vector3.up * 0.1
        local pos2 = climbPos_ + Vector3.up * self.jumpOcclusionDetectOffset + horizontalDir * (- self.jumpOcclusionDetectOffset)
        local pos3 = pos2 + horizontalDir * (self.jumpOcclusionDetectOffset + (self.catColliderRadius * 2))

        -- todo: 改成在 落点上面做个 球体区间检测, 既能确保没有栏杆, 也能确保 落点附近空间足够大
        
        self.catControllerDebug:UpdateOcclusionLines( "Up", pos1, pos2, pos3 ) -- todo: 画

        if self:IsJumpNotOccluded( pos1, pos2, pos3 ) then 
            --self._climbPoint.pos = climbPos_
            return true
        end
    else 
        --print("--- kk 不在猫身前面 ---")
    end 
    return false
end



-- 跳跃路径 是否 没被遮挡
function PlayerControllerQuadruped:IsJumpNotOccluded( pos1, pos2, pos3, pos4 )
    -- 第 1 段:
    local raycastHit1, isHit1 = DreamSpaceLuaUtils.RaycastNearestNonAlloc( pos1, (pos2-pos1), (pos2-pos1).magnitude, jumpCollideLayerMask, self._queryTriggerInteraction )
    if isHit1 == true then 
        --print( "遮挡物-1-: " .. raycastHit1.collider.name )
        return false
    end 

    -- 第 2 段:
    local raycastHit2, isHit2 = DreamSpaceLuaUtils.RaycastNearestNonAlloc( pos2, (pos3-pos2), (pos3-pos2).magnitude, jumpCollideLayerMask, self._queryTriggerInteraction )
    if isHit2 == true then 
        --print( "遮挡物-2-: " .. raycastHit2.collider.name )
        return false
    end 

    -- (可能存在的) 第 3 段:
    if pos4 ~= nil then 
        local raycastHit3, isHit3 = DreamSpaceLuaUtils.RaycastNearestNonAlloc( pos3, (pos4-pos3), (pos4-pos3).magnitude, jumpCollideLayerMask, self._queryTriggerInteraction )
        if isHit3 == true then 
            --print( "遮挡物-3-: " .. raycastHit3.collider.name )
            return false
        end 
    end
    return true
end



-- 上跳: 补救方案
-- 检查上一个 _climbPoint.pos 是否有效, 是否能沿用
function PlayerControllerQuadruped:CanUseLastClimbPos()
    if (self._climbPoint.pos).magnitude < 0.0001 then 
        return false
    end
    assert( isNotNull( self._climbPoint.hitCollider ) )

    local catPos = Vector3.Lerp( self._characterMotor.TransientPosition, self.catHeadTF.position, 0.35 )
    local catHeadPos = self._characterMotor.TransientPosition + self._characterMotor.CharacterForward * self.headFrontDistance

    local lastMoveVec = self._climbPoint.pos - catPos
    local lastDir = Vector3.ProjectOnPlane( lastMoveVec, Vector3.up )
    local lastDis = lastDir.magnitude
    local lastHeightOffset = lastMoveVec.y -- 高度差

    local lastMoveVecToHead = self._climbPoint.pos - catHeadPos
    lastMoveVecToHead. y = 0
    local lastDisToHead = lastMoveVecToHead.magnitude


    local angle = Vector3.Angle( self._characterMotor.CharacterForward, lastDir )

    if  angle > 45.0 then  
        return false
    end 

    if lastDis > self.detectDistance  then 
        return false
    end 

    -- print("koko 距离 " .. tostring(lastDisToHead) )
    -- -- 落点太近时, 可能在猫头顶上方, 要去掉
    -- if lastDisToHead < 0.16  then 
    --     print("koko  太近了")
    --     return false
    -- end 

    if (lastHeightOffset < self.detectHeightMin ) or (lastHeightOffset > self.detectHeightMax) then 
        return false
    end 
    return true
end



-- 从 climbPos 出发向前一段距离后, 平台面是否已结束(此时是深崖),  通过这个检测来规避: "猫跳到一个平台边缘又掉下去" 的问题
function PlayerControllerQuadruped:IsPlatformDeepEnough( climbPos_, forwardDir_, checkDistance_, downDetectLen_ )

    local pos1 = climbPos_ + forwardDir_ * checkDistance_ + Vector3.up * downDetectLen_ * (0.5)

    self.catControllerDebug:UpdateSingleLine( "jumpPlatformDeepDetect", pos1, pos1 + Vector3.down * downDetectLen_, 0.01 ) -- todo: 画

    local raycastHit1, isHit1 = DreamSpaceLuaUtils.RaycastNearestNonAlloc( pos1, Vector3.down, downDetectLen_, jumpCollideLayerMask, self._queryTriggerInteraction )
    
    -- if isHit1 == false then 
    --     print( "koko 平台深度检测 失败" )
    -- end 
    return isHit1
end



