-- 上跳检测: [-- 2 --]
function PlayerControllerQuadruped:DetectClimbable_2()

    -- 起点直接在猫前, 节省一步检测 
    local catPos = self._characterMotor.TransientPosition + self._characterMotor.CharacterForward * self.headFrontDistance

    local heightMin = self._characterMotor.TransientPosition.y + self.detectHeightMin -- 绝对高度值 检测下界
    local heightMax = self._characterMotor.TransientPosition.y + self.detectHeightMax -- 绝对高度值 检测上界

    local srcUpPos   = catPos + Vector3(0, heightMax - catPos.y,0)
    local srcDownPos = catPos + Vector3(0, heightMin - catPos.y,0)

 
    local capsuleRadius = 0.003 -- 直接把这个 capsule 当一个棍子来使
    local forwardDir = self._characterMotor.CharacterForward


    -- [-- 1 --]: "向前打一个竖直的 capsule"
    -- 收集最近碰撞体的 上表面高度 (假设这些 collider 的上表面都是一个平坦水平的表面)
    local raycastHits1, raycastHitsNum = DreamSpaceLuaUtils.CapsuleCastNonAlloc( srcUpPos, srcDownPos, capsuleRadius, forwardDir, self.detectDistance, jumpCollideLayerMask, self._queryTriggerInteraction )

    self.catControllerDebug:UpdateSingleCapsule( "UpCapsule_src", srcUpPos, srcDownPos, capsuleRadius ) -- todo: 画
    self.catControllerDebug:UpdateSingleCapsule( "UpCapsule_dst", srcUpPos + forwardDir * self.detectDistance, srcDownPos + forwardDir * self.detectDistance, capsuleRadius ) -- todo: 画


    if raycastHitsNum > 0 then
        
        local nearestRaycastHit = nil
        for i=0, raycastHitsNum-1 do 
            local rHit = raycastHits1[i]
            
            -- 当 .distance = 0, .point = (0,0,0) 时, 说明这个 collider 在 cast 的起点就和 capsule 相交; 
            -- 由于 角色本体已经被分到 "role" layer, 此时还能检测出这种 collider, 说明 猫的上方有物体,  直接放弃跳跃
            if (rHit.distance < 0.001) and (rHit.point.sqrMagnitude < 0.001 ) then 
                break
            end

            --------
            local hitHeight = rHit.collider.bounds.max.y -- aabb 盒的上表面高度

            if      ((hitHeight > heightMin) and (hitHeight < heightMax)) 
                and ( self:IsTargetTag(rHit.transform) == true )
            then 

                if nearestRaycastHit == nil then 
                    nearestRaycastHit = rHit
                else 
                    if rHit.distance < nearestRaycastHit.distance then 
                        nearestRaycastHit = rHit
                    end 
                end  
            end
        end


        if nearestRaycastHit ~= nil then 
            local climbPos = nearestRaycastHit.point -- 跳跃落脚点

            -- ========= 专门向下打一根射线, 来获得精确高度值 =========
            local height = nearestRaycastHit.collider.bounds.max.y -- 碰撞体上表面高度

            local posA1 = climbPos
            posA1.y = height
            posA1 = posA1 + self._characterMotor.CharacterForward * 0.005 + Vector3.up * 0.1

            local hitInfoA, isHitA = DreamSpaceLuaUtils.RaycastNearestNonAlloc( posA1, Vector3.down, 0.3, jumpCollideLayerMask, self._queryTriggerInteraction )
            if isHitA then 
                height = hitInfoA.point.y
            else 
                print("koko  高度确认射线失败 posA1: " .. posA1:ToString() .. "; 但是这是允许的"  )
            end 
            
            -- ==================            
            climbPos.y = height
            -- ==================  

            self.catControllerDebug:UpdateSinglePoint( "othPoint_1", climbPos, 0.02 ) -- todo: 画 上跳落脚点
            self.catControllerDebug:UpdateSingleLine( "Oth1", catPos, climbPos, 0.01 ) -- todo: 画 黄色的 跳跃路劲线

            -- [-- 2 --]: "在上跳落点上方做 球体区间检测"  确保此处足够空旷
            local sphereRadius = self.catColliderRadius * 0.8
            local spherePos = climbPos + forwardDir * (sphereRadius * 0.7) + Vector3.up * (sphereRadius + 0.03)

            self.catControllerDebug:UpdateSinglePoint( "jumpPointSphere", spherePos, sphereRadius ) -- todo: 画

            local isHit2 = Physics.CheckSphere( spherePos, sphereRadius, jumpCollideLayerMask, self._queryTriggerInteraction )
            if isHit2 == false then

                -- [-- 3 --]: 确保落点附近有足够宽度的 平台,  否则猫容易跳到平台边缘, 然后从边缘掉下去 (过穿)
                if self:IsPlatformDeepEnough( climbPos, forwardDir, sphereRadius * 2 * 0.8,  0.2 ) then 

                    -- 现在, climbPos 就是一个 合格的上跳点;
                    self._upDetectPos = climbPos
                    self._climbPoint.pos = climbPos
                    self._climbPoint.hitCollider = nearestRaycastHit.collider
                    return true
                end
            end

        end
    end


    -- 本次射线没能检测到 合格的 上跳点, 但这不意味着不能跳, 有可能是前方的高台 厚度不够, 下射射线打到 高台后方去了
    -- 廉价的补救措施:
    --     如果上一次得到的有效的 _climbPoint.pos 依然在合理区间内, 那就继续沿用它:
    if self:CanUseLastClimbPos() == true then 
        return true
    end 

    -- 实在不行, 才会把点归零
    --self._upDetectPos = Vector3.zero
    self._climbPoint.pos = Vector3.zero
    self._climbPoint.hitCollider = nil

    return false
end


