-- 下跳
-- [-1-] 向前 打一根射线         -- 确保猫前无遮挡
-- [-2-] 再向斜下方 打一射线      -- 从而找到 下跳点       (先打 2号线, 后打 1号线)
-- [-3-] 在下跳点上方做 球体碰撞   -- 确保下挑点足够空旷
function PlayerControllerQuadruped:DetectLandPos()

    local horizontalDir = self._characterMotor.CharacterForward

    -- 斜着向前下方跳:
    local jumpDir = ( (self.descendDetect.tanVal1 * horizontalDir) + Vector3.down ).normalized

    local pos1 = self._characterMotor.TransientPosition + Vector3.up * 0.05 -- 猫根
    local pos2 = pos1 + horizontalDir * self.descendDetect.distance          -- 猫根 前射一段距离后的点
    local pos3 = pos2 + jumpDir * self.descendDetect.diagonalLen -- 从 pos2 向前斜下方打射线的终点

    
    self.catControllerDebug:UpdateSingleLine( "down_2", pos2, pos3, 0.01 ) -- todo: 画

    -- [-- 2 --]:  "向 斜前下方 打射线"  -- (为在平时节省射线, 这根要先打)
    local hitInfo2, isHit2 = DreamSpaceLuaUtils.RaycastNearestNonAlloc(pos2, jumpDir, self.descendDetect.diagonalLen, jumpCollideLayerMask, self._queryTriggerInteraction)
    local hitPos2 = hitInfo2.point


    if isHit2  and self:IsTargetTag(hitInfo2.transform) then
        local dropHeight = self._characterMotor.TransientPosition.y - hitPos2.y
        if dropHeight >= self.descendDetect.heightMin then

            -- [-- 1 --]:  "从猫根向前打射线"
            -- 确保没有撞到 遮挡物
            local raycastHit1, isHit1 = DreamSpaceLuaUtils.RaycastNearestNonAlloc( pos1, horizontalDir, self.descendDetect.distance, jumpCollideLayerMask, self._queryTriggerInteraction )

            self.catControllerDebug:UpdateSingleLine( "down_1", pos1, pos2, 0.01 ) -- todo: 画

            if isHit1 == false then

                -- [-- 3 --]:  "在目标落点上方做 球体区域碰撞, 确保此地足够空旷没有异物"
                -- !!! 这道检测能有效避免 猫下跳到某个 犄角旮旯里, 最终卡模型
                local sphereRadius = self.catColliderRadius * 0.95 
                local spherePos = hitPos2 + Vector3.up * (sphereRadius + 0.01)

                local isHit3 = Physics.CheckSphere( spherePos, sphereRadius, jumpCollideLayerMask, self._queryTriggerInteraction )
                
                self.catControllerDebug:UpdateSinglePoint( "jumpPointSphere", spherePos, sphereRadius ) -- todo: 画
                
                if isHit3 == false then 
                    self._landDetectPos = hitPos2 -- 为计算下跳前转身
                    self._landPoint.pos = hitPos2 -- 我们想要的 跳跃下落点
                    self._landPoint.dir = jumpDir
                    return true
                end
            end
        end
    end

    -- 本次射线没能检测到 合格的 下跳点, 检查上一次得到的有效的 _landPoint.pos, 若依然在合理区间内, 那就继续沿用它:
    if self:CanUseLastDownPos() == true then 
        return true
    end 

    --self._landPoint.pos = Vector3.zero
    return false
end



-- 是否能沿用 最近一次有效的 下跳落点
function PlayerControllerQuadruped:CanUseLastDownPos()

    ------
    local lastMoveVec = self._landPoint.pos - self._characterMotor.TransientPosition
    local lastDir = Vector3.ProjectOnPlane( lastMoveVec, Vector3.up )
    local lastDis = lastDir.magnitude
    local lastHeightOffset = lastMoveVec.y -- 高度差

    ------------------------------------
    -- 落点需要在 猫前方一个夹角内
    local angle = Vector3.Angle( self._characterMotor.CharacterForward, lastDir )
    if  angle > 50.0 then 
        --print( " -1- 落点不在猫前方夹角内 angle = " .. angle ) 
        return false
    end 

    -- 落点到猫的朝向 变化不能太大
    local angle2 = Vector3.Angle( -lastDir, Vector3.ProjectOnPlane(-self._landPoint.dir, Vector3.up) )
    if  angle2 > 20.0 then  
        --print( " -2- 落点到猫的朝向 变化过大 " ) 
        return false
    end 

    if (lastDis < self.descendDetect.horizontalDistanceMin) or (lastDis > self.descendDetect.horizontalDistanceMax) then 
        --print( " -3- 水平距离不符合 " ) 
        return false
    end 

    -- 垂直高度不能越界
    if ( (-lastHeightOffset) < self.descendDetect.heightMin ) or ((-lastHeightOffset) > self.descendDetect.heightMax ) then 
        --print( " -3- 垂直距离不符合 " ) 
        return false
    end 

    -- =====================  为防止穿模, 需再次做 跳跃路径检测  ======================
    local horizontalDir = lastDir.normalized   
    local pos1 = self._characterMotor.TransientPosition + Vector3.up * 0.05 -- 猫根
    local pos2 = pos1 + horizontalDir * self.descendDetect.distance          -- 猫根 前射一段距离后的点
    local pos3 = self._landPoint.pos + Vector3.up * 0.05 -- 从 pos2 向前斜下方打射线的终点
    local jumpVec = pos3 - pos2

    self.catControllerDebug:UpdateSingleLine( "down_2", pos2, pos3, 0.01 ) -- todo: 画

    -- [-- 2 --]:  "向 斜前下方 打射线"  -- (为在平时节省射线, 这根要先打)
    local hitInfo2, isHit2 = DreamSpaceLuaUtils.RaycastNearestNonAlloc(pos2, jumpVec, jumpVec.magnitude, jumpCollideLayerMask, self._queryTriggerInteraction)


    local hitPos2 = hitInfo2.point

    if isHit2 == false then
        --print( "路径检测 -2- 畅通 " )
        -- [-- 1 --]:  "从猫根向前打射线"
        -- 确保没有撞到 遮挡物
        local raycastHit1, isHit1 = DreamSpaceLuaUtils.RaycastNearestNonAlloc( pos1, horizontalDir, self.descendDetect.distance, jumpCollideLayerMask, self._queryTriggerInteraction )

        self.catControllerDebug:UpdateSingleLine( "down_1", pos1, pos2, 0.01 ) -- todo: 画

        if isHit1 == false then
            --print( "沿用上次的 下落点, " )
            return true
        end     
    end 

    return false
end





-- 边缘检测 - 移动
function PlayerControllerQuadruped:DetectMoveLedge()

    local origin = self._characterMotor.TransientPosition + self._characterMotor.CharacterForward * self.moveLedgeDetectDistanceH + Vector3.up * self.moveLedgeDetectStartHeight

    self.catControllerDebug:UpdateSingleLine( "moveLedge_1", origin, origin + Vector3.down * self.moveLedgeDetectDistanceV, 0.01 ) -- todo: 画

    local raycastHit, isHit = DreamSpaceLuaUtils.RaycastNearestNonAlloc( origin, Vector3.down, self.moveLedgeDetectDistanceV, jumpCollideLayerMask, self._queryTriggerInteraction )
    return not isHit
end


-- 边缘检测 - 前跳
function PlayerControllerQuadruped:DetectJumpLedge()

    local origin = self._characterMotor.TransientPosition + self._characterMotor.CharacterForward * self.jumpLedgeDetectFrontDistance + Vector3.up * self.jumpLedgeDetectStartHeight

    self.catControllerDebug:UpdateSingleLine( "jumpLedge_1", origin, origin + Vector3.down * self.jumpLedgeDetectDistanceV, 0.01 ) -- todo: 画

    local raycastHit, isHit = DreamSpaceLuaUtils.RaycastNearestNonAlloc( origin, Vector3.down, self.jumpLedgeDetectDistanceV, jumpCollideLayerMask, self._queryTriggerInteraction )
    return not isHit
end


-- 鼻前检测 - 移动
function PlayerControllerQuadruped:HeadFrontDetect()

    local backDistance = 0.2 -- 猫头向后偏移一段距离, 以此为起点打射线; 这样就算猫头被埋在墙里了, 也能打到物体
    local dir = self._characterMotor.CharacterForward
    local pos = self.catHeadTF.position + dir * (- backDistance)
    local distance = self.hitWallDistance + backDistance

    self.catControllerDebug:UpdateSingleLine( "moveDir",  pos, pos + dir * distance ) -- todo: 画

    local raycastHits, raycastHitsNum = DreamSpaceLuaUtils.RaycastNonAlloc( pos, dir, distance, jumpCollideLayerMask, self._queryTriggerInteraction )

    for i=0, raycastHitsNum-1 do 

        local hit = raycastHits[i]
        local realDistance = (hit.point - self.catHeadTF.position).magnitude
        local dotVal = Vector3.Dot(dir, -hit.normal );

        if (dotVal > self.hitWallCosVal ) then
            --print("koko 命中, realDistance = " .. tostring(realDistance) )
            return true
        else 
            --print("koko 没命中, realDistance = " .. tostring(realDistance) )
        end
    end

    return false
end



