-- 前跳落点检测
-- 顺带计算 _jumpForwardLandPos
function PlayerControllerQuadruped:DetectJumpForward()

    local headTopPos = self._characterMotor.TransientPosition + Vector3.up * self.jumpForwardDetectStartHeight
    local forwardDistance = self.jumpForwardDetectDistance
    local downDistance = self.jumpForwardDetectEndHeight
    local angle1 = self.jumpForwardAngle1

    local dirMid = self._characterMotor.CharacterForward
    local dirLeft1 = Quaternion.AngleAxis(-angle1, Vector3.up) * self._characterMotor.CharacterForward
    local dirRight1 = Quaternion.AngleAxis(angle1, Vector3.up) * self._characterMotor.CharacterForward

    -- 扇形多次检测:
    if      self:SingleRayDownDetectForward( "forward", "Mid", headTopPos, dirMid, forwardDistance, downDistance)
        or  self:SingleRayDownDetectForward( "forward", "Left1", headTopPos, dirLeft1, forwardDistance, downDistance)
        or  self:SingleRayDownDetectForward( "forward", "Right1", headTopPos, dirRight1, forwardDistance, downDistance)
    then 
        return true
    end

    -- todo: 检测上一次有效点是否合法:
    
    return false
end




-- 前跳
-- returnL bool
function PlayerControllerQuadruped:SingleRayDownDetectForward( bigType_, lineType_, originTopPos, dir, forwardDistance_, downDistance )

    -- [--1--]:
    -- 向前方打第一根射线, 获得最近击中点
    local raycastHit1, isHit1 = DreamSpaceLuaUtils.RaycastNearestNonAlloc( originTopPos, dir, forwardDistance_, jumpCollideLayerMask, self._queryTriggerInteraction )

    local nearestDistance = isHit1 and raycastHit1.distance or 10000.0

    -- 最远前射距离, 如果撞墙, 这个距离会被缩短 (离墙大约 0.1 米)
    local forwardDistance = forwardDistance_
    if isHit1 and (nearestDistance > 0.1)  then 
        forwardDistance = nearestDistance - 0.1 -- 在大斜角时, 其实这个计算不能保证离墙 0.1 米, 但暂掠过
    end

    self.catControllerDebug:UpdateForwardOrUpLines( bigType_, lineType_, originTopPos, dir, forwardDistance, downDistance ) -- todo: 画两根射线

    if (isHit1 == false ) or ( nearestDistance > 0.1 ) then

        local hitInfo2 = nil
        local isHit2 = false 
        if isHit1 then
            -- 前射射线命中, 说明撞墙了:
            local downDetectTopPos2 = originTopPos + (dir * forwardDistance)
            -- [-- 2 --]:  "向下打射线"
            -- 从射线1终点, 向下打射线2, 捕获打中的物体 (上跳平台)
            hitInfo2, isHit2 = DreamSpaceLuaUtils.RaycastNearestNonAlloc( downDetectTopPos2, Vector3.down, downDistance, jumpCollideLayerMask, self._queryTriggerInteraction )
            
        else
            -- 前射射线没有命中, 说明需要做多段 下射检测, 来避免 高台太薄的问题
            local stepLen = (forwardDistance - self.jumpLedgeDetectFrontDistance) / (self.jumpForwardDownLineNums + 0.0001) 

            stepLen = stepLen * 1.1 -- 推荐此处适当变大一点, 能更好地覆盖探测区间

            self.catControllerDebug:UpdateSingleLine( bigType_ .. lineType_ .. "_1", originTopPos, originTopPos + dir * forwardDistance, 0.015 ) -- todo: 画射线
            
            -- 由远及近 向下打射线
            for i=0, self.jumpForwardDownLineNums-1 do

                local downDetectTopPos2 = originTopPos + (dir * (forwardDistance - stepLen * i))
                
                -- [-- 2 --]:  "向下打射线"
                -- 向下打射线2, 捕获打中的物体 (上跳平台)
                hitInfo2, isHit2 = DreamSpaceLuaUtils.RaycastNearestNonAlloc( downDetectTopPos2, Vector3.down, downDistance, jumpCollideLayerMask, self._queryTriggerInteraction )


                if isHit2 and self:IsTargetTag(hitInfo2.transform) then 
                    self.catControllerDebug:UpdateSingleLine( bigType_ .. lineType_ .. "_2", downDetectTopPos2, downDetectTopPos2 + Vector3.down * downDistance, 0.015 ) -- todo: 画射线
                    break
                end 
            end 
        end


        if isHit2  and self:IsTargetTag(hitInfo2.transform) then

            local hitPos2 = hitInfo2.point
            local hitCollider2 = hitInfo2.collider

            local point = hitPos2 + Vector3.down * self._detectDelta
            local ledgePoint = self._characterMotor.TransientPosition + self._characterMotor.CharacterForward * self.jumpLedgeDetectFrontDistance
        
            -- 边缘检测起始点的 xz值, 前跳 DetectPos 的 y值;
            local origin = Vector3(ledgePoint.x, point.y, ledgePoint.z)
        
            local direction = Vector3.ProjectOnPlane(point - origin, Vector3.up).normalized
            
            -- [--3--]:
            -- 从射线1起点, 平行于 xz 平面, 沿着 hitPos2 下面一点的高度, 打向 候选跳跃点
            -- 看看中间是否能命中 射线2 命中的物体
            local hitInfo3, isHit3 = DreamSpaceLuaUtils.RaycastNearestNonAlloc( origin, direction, self.jumpForwardDetectDistance, jumpCollideLayerMask, self._queryTriggerInteraction )
        
            self.catControllerDebug:UpdateJumpLedgeLine_2( origin, origin + direction * self.jumpForwardDetectDistance, isHit3 ) -- todo: 画
        
            if isHit3  and self:IsTargetTag(hitInfo3.transform) then
        
                assert( hitCollider2 ~= nil )
        
                -- 如果不判断下 前后两次 hit 的物体是否相同, 就会出现 "猫跳到台子的脚跟处" 的问题 
                if hitCollider2 == hitInfo3.collider then 

                    -- [--4--]:
                    -- 检测猫脚下的地面, 确保 hitObj2 不和地面是同物体 
                    -- RaycastHit[]
                    local raycastHits4, raycastHits4Num = self:DetectCurrentLand()

                    local isHitLand = false
                    for i=0, raycastHits4Num-1 do 
                        -- RaycastHit
                        local hitInfo4 = raycastHits4[i]
                        if hitInfo4.collider == hitCollider2 then 
                            isHitLand = true 
                            break
                        end
                    end

                    -- 我们想要的
                    if isHitLand == false then 

                        local landPos = hitInfo3.point
                        landPos.y = hitPos2.y
                        -------
                        -- [--5--]: "检查跳跃路径上是否存在遮挡"
                        local pos11 = self._characterMotor.TransientPosition + Vector3.up * self.jumpOcclusionDetectOffset
                        local horizontalDir = Vector3.ProjectOnPlane(landPos - pos11, Vector3.up).normalized

                        local pos22 = pos11 + horizontalDir * self.jumpLedgeDetectFrontDistance
                        local pos33 = landPos + Vector3.up * self.jumpOcclusionDetectOffset + horizontalDir * (- self.jumpOcclusionDetectOffset)
                        local pos44 = pos33 + horizontalDir * 2 * self.jumpOcclusionDetectOffset

                        self.catControllerDebug:UpdateOcclusionLines( "Forward", pos11, pos22, pos33, pos44 ) -- todo: 画

                        if self:IsJumpNotOccluded( pos11, pos22, pos33, pos44 ) then 

                            self._jumpForwardDownDetectPos = hitPos2 -- 保留方向信息, 此pos 不会被清空
                            --self._jumpForwardLandPos = landPos -- 我们要的 前跳落点
                            self._jumpForwardLandPos = landPos + self._characterMotor.CharacterForward * 0.15 -- 我们要的 前跳落点 (第二版, 再往前一点, 防止猫掉下去)
                            self.catControllerDebug:UpdateJumpForwardDetectPoint( hitPos2 )  -- todo: 画

                            return true
                        end
                    end
                end
            end
            self._jumpForwardLandPos = Vector3.zero
        end 
    end
    return false
end



-- 检测猫当前脚下的地面
function PlayerControllerQuadruped:DetectCurrentLand()

    local origin = self._characterMotor.TransientPosition + Vector3.up * 0.01
    local detectLen = 0.1

    self.catControllerDebug:UpdateSingleLine( "land_1", origin, origin + Vector3.down * detectLen, 0.03 ) -- todo: 画

    -- RaycastHit[]
    --local raycastHits = Physics.RaycastAll( origin, Vector3.down, detectLen )
    --return raycastHits 

    local raycastHits, raycastHitsNum = DreamSpaceLuaUtils.RaycastNonAlloc_3( origin, Vector3.down, detectLen )
    return raycastHits, raycastHitsNum
end




