function PlayerControllerQuadruped:JumpForwardVerticalModify()
    local deltaY = self._jumpForwardLandPos.y - self._characterMotor.TransientPosition.y
    if deltaY > 0 then
        -- 上升阶段加高度
        self._jumpForwardModifyVStartTime = self.jumpForwardRiseStartTime
        self._jumpForwardModifyVTime = self.jumpForwardDescendStartTime - self.jumpForwardRiseStartTime
    else
        -- 下降阶段加高度
        self._jumpForwardModifyVStartTime = self.jumpForwardDescendStartTime
        self._jumpForwardModifyVTime = self.jumpForwardDescendEndTime - self.jumpForwardDescendStartTime
    end

    self._jumpForwardModifyVing = false
    self._hasJumpForwardModifyStart = false
    self._jumpForwardModifyVTimer = 0
    self._jumpForwardModifyVStartTimer = 0
    self._jumpForwardFromV = self._characterMotor.TransientPosition.y
    self._jumpForwardToV = self._jumpForwardLandPos.y
end



function PlayerControllerQuadruped:UpdateJumpForwardVerticalModify(deltaTime)
    self._jumpForwardModifyVStartTimer = self._jumpForwardModifyVStartTimer + deltaTime
    
    if (not self._hasJumpForwardModifyStart and self._jumpForwardModifyVStartTimer > self._jumpForwardModifyVStartTime and not self._jumpForwardModifyVing) then
        self._hasJumpForwardModifyStart = true
        self._jumpForwardModifyVing = true
    end
    
    if (self._jumpForwardModifyVing) then
        self._jumpForwardModifyVTimer = self._jumpForwardModifyVTimer + deltaTime
        local progress = self._jumpForwardModifyVTimer / self._jumpForwardModifyVTime
        if (progress >= 1) then
            self._jumpForwardModifyVing = false
        else
            local currentY = Mathf.Lerp(self._jumpForwardFromV, self._jumpForwardToV, progress)
            local deltaY = currentY - self._characterMotor.TransientPosition.y
            self._character:Move(Vector3.up * deltaY)
        end
    end
end


-- 从多个命中结果中找到y值最大的一个
function PlayerControllerQuadruped:GetToppestHitResult(results, count)
    local yMax = -math.huge
    local index = 0
    for i = 1, count do
        local y = results[i].point.y
        if (y > yMax) then
            yMax = y
            index = i
        end
    end
    return index
end






function PlayerControllerQuadruped:IsTargetTag(which)
    if (self.useIgnoreTags) then
        local length = #self.jumpIgnoreTags
        if (length == 0) then
            return true
        else
            return not KTool.ContainAnyTag(which, self.jumpIgnoreTags)
        end
    else
        local length = #self.jumpTags
        if (length == 0) then
            return true
        else
            return KTool.ContainAnyTag(which, self.jumpTags)
        end
    end
end

-- ========================================================================================================================================== 

function PlayerControllerQuadruped:JumpDetect()



    -- 上跳检测
    local isJumpUpEnable = self:DetectClimbable_2()
    --if self:DetectClimbable()  then
    if isJumpUpEnable == true  then

        self._canJumpUp = true

        self.catControllerDebug:UpdateSinglePoint( "upPoint", self._climbPoint.pos, 0.03 ) -- todo: 画

        if JumpPositionSmooth.GetActive() then

            self._jumpUpSmooth:SetShow(true)
            self._jumpUpSmooth:SetTargetPos(self._climbPoint.pos)
        else 
            JumpHint.ShowJumpHint(JumpHintType.Up, self._climbPoint.pos)
        end
        
    else

        self._climbPoint.pos = Vector3.zero
        self._canJumpUp = false
        if JumpPositionSmooth.GetActive() then
            self._jumpUpSmooth:SetShow(false)
        else 
            JumpHint.HideJumpHint(JumpHintType.Up)
        end
    end  
    
    -- 下跳检测
    if self:DetectLandPos() then
        self._canJumpDown = true

        self.catControllerDebug:UpdateSinglePoint( "downPoint", self._landPoint.pos, 0.07 ) -- todo: 画

        if JumpPositionSmooth.GetActive() then
            self._jumpDownSmooth:SetShow( true )
            self._jumpDownSmooth:SetTargetPos( self._landPoint.pos )
        else
            JumpHint.ShowJumpHint(JumpHintType.Down, self._landPoint.pos )
        end
    else
        --self._landPoint.pos = Vector3.zero
        self._canJumpDown = false
        if JumpPositionSmooth.GetActive() then
            self._jumpDownSmooth:SetShow( false )
        else
            JumpHint.HideJumpHint(JumpHintType.Down)
        end
    end

    -- 前跳检测
    if      isJumpUpEnable == false -- 当允许上跳时, 不再允许前跳, 以此来规避 "两个 jump hint ui 重叠" 而导致无法点击 ui 的 bug;
        and self:DetectJumpLedge() and self:DetectJumpForward() 
    then
        -- 前跳落点检测
        if PlayerControllerQuadruped.AlmostZero( self._jumpForwardLandPos ) == true then

            -- 没有找到合适的落点，可能是不可到达
            self._jumpForwardLandPos = Vector3.zero
            self._canJumpForward = false
            if JumpPositionSmooth.GetActive() then
                self._jumpForwardSmooth:SetShow(false)
            else
                JumpHint.HideJumpHint(JumpHintType.Forward)
            end
        else
            self._canJumpForward = true
            if JumpPositionSmooth.GetActive() then
                self._jumpForwardSmooth:SetShow(true)
                self._jumpForwardSmooth:SetTargetPos(self._jumpForwardLandPos)

                self.catControllerDebug:UpdateSinglePoint( "forwardPoint", self._jumpForwardLandPos, 0.07 ) -- todo: 画
            else
                JumpHint.ShowJumpHint(JumpHintType.Forward, self._jumpForwardLandPos)
            end
        end
    else
        self._jumpForwardLandPos = Vector3.zero
        self._canJumpForward = false
        if JumpPositionSmooth.GetActive() then
            self._jumpForwardSmooth:SetShow(false)
        else
            JumpHint.HideJumpHint(JumpHintType.Forward)
        end
    end
end


function PlayerControllerQuadruped.AlmostZero( v3_ )
    return  Mathf.Abs(v3_.x) < 0.0001
        and Mathf.Abs(v3_.y) < 0.0001
        and Mathf.Abs(v3_.z) < 0.0001
end


function PlayerControllerQuadruped:TryExitIdleModtion()
    if self._idleMotioning and not self._idleMotionExitting then
        self._idleMotioning = false
        self._idleMotionExitting = true
        local stateInfo = self._character.AnimationAdapter:GetCurrentAnimatorStateInfo(0)
        if stateInfo:IsName("Sitting") then
            self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.SittingToIdle, 0)
        elseif stateInfo:IsName("Lying") then
            self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.LyingToIdle, 0)
        elseif stateInfo:IsName("IdleToSit") then
            self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.SittingToIdle, 0.2)
        elseif stateInfo:IsName("SitToLying") then
            self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.LyingToIdle, 0.2)
        end
    end
end




function PlayerControllerQuadruped:UpdateFootStepState( forwardValue_, jumptState_ )

    -- walk 还是 run 需要靠计算 
    -- JumpStart 还是 JumpEnd 则是手动指定
    if jumptState_ == nil then 
        self.currentFootStepState = (forwardValue_ < 0.01) and FootStepState.Idle or 
            ( (forwardValue_ < 0.8) and FootStepState.Walk or FootStepState.Run )
    else 
        assert( jumptState_ == FootStepState.JumpStart or jumptState_ == FootStepState.JumpEnd )
        self.currentFootStepState = jumptState_
    end

    -- 发生切换时:
    if self.currentFootStepState ~= self.oldFootStepState then 

        for _,func in pairs(self.WhenPlayerMoveStateChangeds) do 
            assert( isNotNull(func) )
            func( self.currentFootStepState, self.oldFootStepState )
        end

        self.oldFootStepState = self.currentFootStepState
    end
end



function PlayerControllerQuadruped:WhenCallEvent_Effect( name )

    if name == "JumpStart" then 
        self:UpdateFootStepState( 0, FootStepState.JumpStart )
    elseif name == "JumpEnd" then
        self:UpdateFootStepState( 0, FootStepState.JumpEnd )
        --print("音效事件：跳跃end")
    end


    if name == "Foot" then 
        --print( "触发动画 event Foot" )
        --print("音效事件：脚步声")
        if (DreamSpaceStates.environmentType == DreamSpaceStates.EnvironmentType.InPipe) then
            DreamSpaceSounds.Play( DreamSpaceSounds.sfx.catWalkMetal )
        else
            DreamSpaceSounds.Play( DreamSpaceSounds.sfx.catRun )
        end

    end
    
end




return PlayerControllerQuadruped